configuration.bicep:
resource blobSvc 'Microsoft.Storage/storageAccounts/blobServices@2023-05-01' existing = {
  name: 'stcontoso01/default'
}
resource reports 'Microsoft.Storage/storageAccounts/blobServices/containers@2023-05-01' = {
  parent: blobSvc
  name: 'reports'
  properties: { publicAccess: 'None' }
}
resource fileSvc 'Microsoft.Storage/storageAccounts/fileServices@2023-05-01' existing = {
  name: 'stcontoso01/default'
}
resource finance 'Microsoft.Storage/storageAccounts/fileServices/shares@2023-05-01' = {
  parent: fileSvc
  name: 'finance'
  properties: { shareQuota: 2048, accessTier: 'Hot' }
}
